from __future__ import annotations

"""Preview Omni-style case routing with SLA-aware ordering (starter is priority-first)."""

from service_models import AgentCapacity, OPEN_STATUSES, SupportCase
from sla_sort import is_near_milestone_breach, minutes_until_milestone, routing_tuple_priority_first


PRIORITY_RANK = {
    "Critical": 0,
    "High": 1,
    "Medium": 2,
    "Low": 3,
}


def _minutes_to_breach(case: SupportCase, current_minute: int) -> int:
    return minutes_until_milestone(case, current_minute)


def _is_near_breach(case: SupportCase, current_minute: int) -> bool:
    return is_near_milestone_breach(case, current_minute)


def _routing_key(case: SupportCase, current_minute: int) -> tuple[int, int, int, str]:
    pr = PRIORITY_RANK[case.priority]
    mtb = _minutes_to_breach(case, current_minute)
    # Participant: use `routing_tuple_milestone_first` once near-breach ordering is required.
    return routing_tuple_priority_first(case, pr, mtb)


def _case_summary(case: SupportCase, current_minute: int, reason: str) -> dict[str, object]:
    return {
        "case_id": case.case_id,
        "account_tier": case.account_tier,
        "priority": case.priority,
        "status": case.status,
        "minutes_to_breach": _minutes_to_breach(case, current_minute),
        "near_breach": _is_near_breach(case, current_minute),
        "reason": reason,
    }


ROUTING_RESULT_KEYS = (
    "assigned_count",
    "waiting_count",
    "skipped_count",
    "near_breach_count",
    "assigned_cases",
    "waiting_cases",
    "skipped_cases",
    "near_breach_cases",
)


def routing_report_field_count() -> int:
    return len(ROUTING_RESULT_KEYS)


def route_service_cases(
    cases: list[SupportCase],
    capacity: AgentCapacity,
    current_minute: int,
) -> dict[str, object]:
    eligible = [case for case in cases if case.status in OPEN_STATUSES]
    skipped = [
        _case_summary(case, current_minute, "case_not_open")
        for case in cases
        if case.status not in OPEN_STATUSES
    ]
    ordered = sorted(eligible, key=lambda c: _routing_key(c, current_minute))
    assigned_cases = ordered[: capacity.available_slots]
    waiting_cases = ordered[capacity.available_slots :]

    return summarize_case_routing(
        [_case_summary(case, current_minute, "assigned") for case in assigned_cases],
        [_case_summary(case, current_minute, "waiting_for_capacity") for case in waiting_cases],
        skipped,
    )


def summarize_case_routing(
    assigned_cases: list[dict[str, object]],
    waiting_cases: list[dict[str, object]],
    skipped_cases: list[dict[str, object]],
) -> dict[str, object]:
    all_open = assigned_cases + waiting_cases
    near_breach_cases = [row for row in all_open if row["near_breach"]]
    return {
        "assigned_count": len(assigned_cases),
        "waiting_count": len(waiting_cases),
        "skipped_count": len(skipped_cases),
        "near_breach_count": len(near_breach_cases),
        "assigned_cases": assigned_cases,
        "waiting_cases": waiting_cases,
        "skipped_cases": skipped_cases,
        "near_breach_cases": near_breach_cases,
    }


class ServiceCloudCaseRouter:
    def __init__(self, capacity: AgentCapacity) -> None:
        self.capacity = capacity

    def route(self, cases: list[SupportCase], current_minute: int) -> dict[str, object]:
        return route_service_cases(cases, self.capacity, current_minute)

