from __future__ import annotations

from dataclasses import dataclass


VALID_PRIORITIES = {"Critical", "High", "Medium", "Low"}
OPEN_STATUSES = {"New", "Open", "Working"}


def _non_empty(label: str, value: str) -> None:
    if not value.strip():
        raise ValueError(f"{label} required")


@dataclass(frozen=True)
class SupportCase:
    case_id: str
    account_tier: str
    priority: str
    status: str
    created_minute: int
    milestone_due_minute: int

    def __post_init__(self) -> None:
        _non_empty("case_id", self.case_id)
        _non_empty("account_tier", self.account_tier)
        if self.priority not in VALID_PRIORITIES:
            raise ValueError("unsupported priority")
        _non_empty("status", self.status)
        if self.created_minute < 0:
            raise ValueError("created_minute must be non-negative")
        if self.milestone_due_minute < self.created_minute:
            raise ValueError("milestone_due_minute cannot be before created_minute")

    def is_open(self) -> bool:
        return self.status in OPEN_STATUSES

    def service_identity(self) -> tuple[str, str]:
        return (self.case_id.strip(), self.account_tier.strip())


@dataclass(frozen=True)
class AgentCapacity:
    queue_name: str
    available_slots: int

    def __post_init__(self) -> None:
        _non_empty("queue_name", self.queue_name)
        if self.available_slots < 0:
            raise ValueError("available_slots must be non-negative")

    def capacity_token(self) -> str:
        return f"{self.queue_name.strip()}#{self.available_slots}"


def priority_is_enterprise_tier(tier: str) -> bool:
    return tier.strip().lower() in {"enterprise", "strategic"}


def milestone_span_days_hint(created: int, due: int) -> int:
    return max(0, due - created)


def case_age_minutes(created_minute: int, current_minute: int) -> int:
    return max(0, current_minute - created_minute)


def status_allows_routing(status: str) -> bool:
    return status in OPEN_STATUSES


def tier_weight_for_preview(tier: str) -> int:
    lowered = tier.strip().lower()
    if lowered in {"platinum", "strategic"}:
        return 3
    if lowered == "enterprise":
        return 2
    if lowered == "commercial":
        return 1
    return 0


def queue_slot_hint(queue_name: str, slots: int) -> str:
    return f"{queue_name.strip()} slots={slots}"


def validate_milestone_sequence(created: int, due: int) -> None:
    if due < created:
        raise ValueError("milestone_due_minute cannot be before created_minute")

