from __future__ import annotations

"""Sort keys for Service Cloud routing previews (starter: static priority wins over SLA)."""

from service_models import SupportCase

NEAR_BREACH_THRESHOLD_MINUTES = 30


def minutes_until_milestone(case: SupportCase, current_minute: int) -> int:
    return case.milestone_due_minute - current_minute


def is_near_milestone_breach(case: SupportCase, current_minute: int) -> bool:
    return minutes_until_milestone(case, current_minute) <= NEAR_BREACH_THRESHOLD_MINUTES


def routing_tuple_priority_first(
    case: SupportCase,
    priority_rank: int,
    minutes_to_breach: int,
) -> tuple[int, int, int, str]:
    """Starter bug: `priority_rank` dominates before SLA urgency."""
    return (priority_rank, minutes_to_breach, case.created_minute, case.case_id)


def routing_tuple_milestone_first(
    case: SupportCase,
    priority_rank: int,
    minutes_to_breach: int,
    near_breach: bool,
) -> tuple[int, int, int, int, str]:
    """Participant: near-breach work clears before lower-urgency backlog, then priority."""
    if near_breach:
        return (0, minutes_to_breach, priority_rank, case.created_minute, case.case_id)
    return (1, priority_rank, minutes_to_breach, case.created_minute, case.case_id)


def describe_queue_health(near_breach_count: int, waiting_count: int) -> str:
    if near_breach_count and waiting_count:
        return "constrained_with_sla_pressure"
    if near_breach_count:
        return "sla_pressure"
    if waiting_count:
        return "capacity_constrained"
    return "healthy"


def omni_channel_lane_hint(tier: str) -> str:
    return f"lane::{tier.strip().lower()}"


def breach_clock_label(minutes_to_breach: int) -> str:
    if minutes_to_breach < 0:
        return "breached"
    if minutes_to_breach <= NEAR_BREACH_THRESHOLD_MINUTES:
        return "near"
    return "safe"


def stable_case_tiebreak(left_id: str, right_id: str) -> bool:
    return left_id < right_id


def priority_name_from_rank(rank: int) -> str:
    inverse = {0: "Critical", 1: "High", 2: "Medium", 3: "Low"}
    return inverse.get(rank, "Unknown")


def audit_reason_assigned() -> str:
    return "assigned"


def audit_reason_waiting() -> str:
    return "waiting_for_capacity"


def format_minutes_remaining(minutes: int) -> str:
    return f"{minutes}m"


def escalation_risk_score(near_breach: bool, tier: str) -> int:
    score = 2 if near_breach else 0
    if tier.lower() == "enterprise":
        score += 1
    return score

